const body = $input.first().json.body ?? $input.first().json;
const message = body.message ?? body;
const type = message.type ?? body.type ?? '';
if (type !== 'end-of-call-report') { return [{json:{accepted:false,reason:'Expected end-of-call-report',eventType:type}}]; }
const call = message.call ?? {};
const structured = message.analysis?.structuredData ?? message.structuredData ?? {};
const str = value => value == null ? '' : String(value).trim();
const name = str(structured.caller_name ?? structured.name);
const email = str(structured.email).toLowerCase();
const phone = str(structured.phone_number ?? structured.phone ?? call.customer?.number);
const interest = str(structured.interest ?? structured.reason_for_call);
const requested = Boolean(structured.appointment_requested ?? structured.wants_appointment);
const doNotCall = Boolean(structured.do_not_call ?? structured.opt_out);
const validEmail = /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email);
const qualified = !doNotCall && Boolean(name) && (validEmail || Boolean(phone)) && Boolean(interest);
return [{json:{accepted:true,source:'vapi',eventType:type,callId:str(call.id ?? message.callId),lead:{name,email:validEmail?email:'',phone,interest,appointmentRequested:requested,doNotCall},qualification:{qualified,reason:doNotCall?'Opted out':qualified?'Contact information and interest provided':'Missing contact information or interest'},crmPayload:{external_call_id:str(call.id ?? message.callId),full_name:name,email:validEmail?email:'',phone,notes:interest,status:doNotCall?'do_not_contact':qualified?'qualified':'needs_review',appointment_requested:requested},demo:true}}];
